import { motion } from "framer-motion";
import ownerImg from "../assets/Owner.jpg";

export default function Trainers() {
  return (
    <section
      id="trainers"
      className="bg-black py-24 px-6 border-t border-white/10"
    >
      <div className="max-w-7xl mx-auto">

        {/* TITLE */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="mb-16"
        >
          <h2 className="text-4xl md:text-5xl font-bold text-white">
            Hear it from <span className="text-[#e9b21a]">Our Owner</span>
          </h2>
          <div className="mt-4 w-24 h-1 bg-[#e9b21a]" />
          <p className="mt-6 text-gray-400 max-w-3xl">
            A personal message about discipline, consistency, and the mindset
            that builds real transformation at Bodyzeal Fitworks.
          </p>
        </motion.div>

        {/* CONTENT */}
        <div className="grid md:grid-cols-2 gap-14 items-center">

          {/* LEFT – OWNER IMAGE */}
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
            className="relative"
          >
            <img
              src={ownerImg}
              alt="Bodyzeal Owner"
              className="w-full h-[480px] object-cover rounded-xl border border-white/10"
            />

            {/* NAME STRIP */}
            <div className="absolute bottom-4 left-4 right-4 bg-black/80 border border-[#e9b21a]/40 px-6 py-4 rounded-lg">
              <p className="text-lg font-semibold text-white">
                Founder & Head Coach
              </p>
              <p className="text-sm text-[#e9b21a]">
                Bodyzeal Fitworks
              </p>
            </div>
          </motion.div>

          {/* RIGHT – TEXT + VIDEO */}
          <motion.div
            initial={{ opacity: 0, x: 30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
            className="space-y-8"
          >
            {/* MESSAGE */}
            <p className="text-gray-300 text-lg leading-relaxed">
              At Bodyzeal Fitworks, fitness is not about shortcuts or temporary
              motivation. It’s about showing up every day, mastering the basics,
              and building a body and mindset that lasts a lifetime.
              <br /><br />
              Every client here trains with purpose. Every program is structured.
              And every result is earned through discipline.
            </p>

            {/* VIDEO */}
            <div className="border border-[#e9b21a]/30 rounded-xl overflow-hidden">
              <video
                controls
                className="w-full h-64 object-cover bg-black"
                poster="https://images.unsplash.com/photo-1517836357463-d25dfeac3438"
              >
                <source
                  src="https://cdn.pixabay.com/video/2020/10/26/53378-474373687_large.mp4"
                  type="video/mp4"
                />
              </video>
            </div>
          </motion.div>

        </div>
      </div>
    </section>
  );
}
